"""B43 read-only saved-evidence collation. Never launches compiler/diagnostics."""
import hashlib
import json
from collections import Counter
from pathlib import Path

E = Path(__file__).resolve().parent
HOST = Path('/private/tmp/sifr-b42-host.FVuvOb')
anchors = {
    str(HOST / 'evidence/terminal.json'): '0b5f61e533e39d75aa0dc847aada4d7d6b805eaa496ef1201fb4a4909d5de16a',
    '/private/tmp/sifr-b42.TzkTjs/evidence/terminal.json': '17dac010d8415dc64c13725c1f684be570c20bee52dc64aef84a37c14b2043b0',
    '/private/tmp/sifr-b41.rVHbYl/evidence/terminal.json': 'd94e1e2d167ce818c1073dd49d93a69ff9fc0e9587149bd08a9315dade786304',
    '/private/tmp/sifr-b19.udje7q/evidence/terminal.json': '190df22816de0acdefcd6a438c1bac3a074d582fa52bbaed1e8a0befa2f27b05',
    '/private/tmp/sifr-b20.bj6Au6/evidence/terminal.json': '0b4fe5b32beb604527091fdfbeab9ff3b4b7dbd6d4d194e27ebb17d3260999dc',
}
bound = {}

def authenticate(path, expected):
    path = Path(path)
    data = path.read_bytes()
    actual = hashlib.sha256(data).hexdigest()
    if actual != expected:
        raise ValueError(f'Authentication mismatch: {path}: {actual} != {expected}')
    bound[str(path)] = {'sha256': actual, 'bytes': len(data)}
    return json.loads(data) if path.suffix == '.json' else data

terminals = {p: authenticate(p, h) for p, h in anchors.items()}
counts = {}
for p, terminal in terminals.items():
    if 'evidence_sha256' in terminal:
        rows = terminal['evidence_sha256']
        for name, digest in rows.items():
            authenticate(name, digest)
        counts[p] = len(rows)
        continue
    item = terminal.get('evidence_inventory', terminal.get('inventory'))
    if item:
        inventory = authenticate(item['path'], item['sha256'])
        rows = inventory.get('artifacts', inventory.get('files', inventory))
        if isinstance(rows, list):
            for row in rows:
                authenticate(row['path'], row['sha256'])
        elif isinstance(rows, dict):
            for name, row in rows.items():
                authenticate(name, row if isinstance(row, str) else row['sha256'])
        else:
            raise ValueError(f'Unknown inventory shape: {item}')
        counts[p] = len(rows)

receipt = json.loads((HOST / 'evidence/representative-01.json').read_text())
processes = receipt['observed_processes']
cargos = [p for p in processes if '/bin/cargo ' in p['command'] or p['command'].startswith('cargo ')]
rustcs = [p for p in processes if ' --crate-name ' in p['command']]
retained = []
for path in sorted((HOST / 'tmp').glob('sifr_rust_probe_*/**/*')):
    if path.is_file():
        data = path.read_bytes()
        retained.append({'path': str(path), 'sha256': hashlib.sha256(data).hexdigest(),
                         'bytes': len(data), 'mtime_ns': path.stat().st_mtime_ns,
                         'content': data.decode(), 'custody': 'retained at B43; not in B42-HOST sealed inventory'})
markers = []
for path in sorted((HOST / 'tmp/sifr_generated_artifact_cache/rust_bridge_probes').glob('*.ok')):
    data = path.read_bytes()
    markers.append({'path': str(path), 'sha256': hashlib.sha256(data).hexdigest(),
                    'bytes': len(data), 'mtime_ns': path.stat().st_mtime_ns})
summary = {'authenticated_inventory_counts': counts, 'bound': bound,
           'process_count': len(processes), 'cargo_count': len(cargos),
           'rustc_count': len(rustcs), 'cargo_processes': cargos,
           'rustc_crates': dict(Counter(p['command'].split(' --crate-name ')[1].split()[0] for p in rustcs)),
           'rustc_processes': rustcs, 'retained_probes': retained, 'retained_markers': markers,
           'observation_limit': 'Supervisor retains last seen row per PID, start time seconds only; no exit/per-snapshot/CPU trace. New file metadata is not original sealed timing evidence.'}
(E / 'saved-analysis.json').write_text(json.dumps(summary, indent=2) + '\n')
print(json.dumps({k: summary[k] for k in ['authenticated_inventory_counts', 'process_count', 'cargo_count', 'rustc_count', 'rustc_crates']}, indent=2))
print('retained_probe_files', len(retained), 'retained_ok_markers', len(markers))
for p in cargos:
    print(p['pid'], p['ppid'], p['start'], p['command'])
